use generated_gpui_component::CompiledComponent;
use gpui::{AppContext, TestAppContext, VisualTestContext};
use serde_json::{json, Value as Json};

#[gpui::test]
fn watcher_groups_metadata_and_same_value_are_observed_in_an_actual_window(cx: &mut TestAppContext) {
    let window = cx.update(|cx| cx.open_window(Default::default(), |window, cx| {
        cx.new(|cx| CompiledComponent::new(json!({"label":"first","count":1,"extra":"old"}), None, window, cx))
    }).unwrap());
    let mut cx = VisualTestContext::from_window(window.into(), cx);
    let component = window.root(&mut cx).unwrap();
    let handle = component.read_with(&cx, |component, _| component.handle());
    cx.run_until_parked();
    assert!(handle.owner.borrow().mounted, "actual SDK window must commit the physical view");
    assert_eq!(handle.state("trace"), json!(""));
    assert!(handle.take_events().is_empty(), "initial hydration must not dispatch");
    cx.update(|window, cx| component.update(cx, |component, cx| component.set_props(json!({"label":"second","count":2,"extra":"new"}), window, cx)));
    cx.run_until_parked();
    assert_eq!(handle.state("trace"), json!("raw-all|raw-keys|resolved-label|resolved-all|resolved-count|"));
    let events = handle.take_events();
    assert_eq!(events.iter().map(|(_,payload)|payload["kind"].as_str().unwrap()).collect::<Vec<_>>(), vec!["raw-all","raw-keys","resolved-label","resolved-all","resolved-count"]);
    // Native input is serde_json's own ordered object, not an invented JavaScript raw snapshot.
    assert_eq!(events[0].1["all"], json!(["count","extra","label"]));
    assert_eq!(events[0].1["matched"], events[0].1["all"]);
    assert_eq!(events[1].1["matched"], json!(["extra","label"]));
    assert_eq!(events[2].1["next"], json!("second"));
    assert_eq!(events[2].1["prev"], json!("first"));
    assert_eq!(events[4].1["next"].as_f64(), Some(2.0));
    println!("GPUI_WATCH_FIRST {}", serde_json::to_string(&events).unwrap());
    cx.update(|window, cx| component.update(cx, |component, cx| component.set_props(json!({"label":"second","count":2,"extra":"new"}), window, cx)));
    cx.run_until_parked();
    assert!(handle.take_events().is_empty(), "unchanged primitive input is not a delivery event");
    cx.update(|window, cx| component.update(cx, |component, cx| component.set_props(json!({"label":17,"count":2,"extra":"new"}), window, cx)));
    cx.run_until_parked();
    let events = handle.take_events();
    assert_eq!(events.iter().map(|(_,payload)|payload["kind"].as_str().unwrap()).collect::<Vec<_>>(), vec!["raw-all","raw-keys"]);
    println!("GPUI_WATCH_INVALID {}", serde_json::to_string(&events).unwrap());
    cx.update(|window, cx| component.update(cx, |component, cx| component.set_props(json!({"count":2,"extra":"new"}), window, cx)));
    cx.run_until_parked();
    let events = handle.take_events();
    assert_eq!(events.iter().map(|(_,payload)|payload["kind"].as_str().unwrap()).collect::<Vec<_>>(), vec!["raw-all","raw-keys","resolved-label","resolved-all"]);
    assert_eq!(events[2].1["next"], json!("default"));
    assert_eq!(events[2].1["prev"], json!("second"));
    println!("GPUI_WATCH_MISSING {}", serde_json::to_string(&events).unwrap());
    for count in [0.0_f64, -0.0_f64] {
        cx.update(|window, cx| component.update(cx, |component, cx| component.set_props(json!({"count":count,"extra":"new"}), window, cx)));
        cx.run_until_parked();
        let events = handle.take_events();
        assert_eq!(events.iter().map(|(_,payload)|payload["kind"].as_str().unwrap()).collect::<Vec<_>>(), vec!["raw-all","resolved-all","resolved-count"]);
        let observed = events[2].1["next"].as_f64().unwrap();
        assert_eq!(observed.to_bits(), count.to_bits(), "signed-zero change must preserve Object.is semantics");
        println!("GPUI_WATCH_ZERO negative={} {}", count.is_sign_negative(), serde_json::to_string(&events).unwrap());
    }
    cx.update(|window, cx| handle.dispose(window, cx));
    cx.run_until_parked();
    assert!(handle.owner.borrow().disposed);
    assert!(!handle.owner.borrow().mounted);
    assert!(handle.owner.borrow().exposes.is_empty());
    println!("GPUI_WATCH_TERMINAL disposed=true mounted=false exposes=empty");
}

